ALTER TABLE "storefront_settings" ADD COLUMN "checkout_enabled" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "tax_rate" DECIMAL(5,2) NOT NULL DEFAULT 0, ADD COLUMN "prices_include_tax" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "reservation_minutes" INTEGER NOT NULL DEFAULT 30;
ALTER TABLE "storefront_settings" ADD CONSTRAINT "store_tax_range" CHECK (tax_rate BETWEEN 0 AND 100), ADD CONSTRAINT "store_hold_range" CHECK (reservation_minutes BETWEEN 5 AND 1440);
ALTER TABLE "products" ADD COLUMN "reserved_quantity" DECIMAL(14,3) NOT NULL DEFAULT 0;
ALTER TABLE "products" ADD CONSTRAINT "products_store_reserved_check" CHECK (reserved_quantity >= 0 AND (reserved_quantity = 0 OR stock_quantity >= reserved_quantity));
ALTER TABLE "product_batches" ADD COLUMN "reserved_quantity" DECIMAL(14,3) NOT NULL DEFAULT 0;
ALTER TABLE "product_batches" ADD CONSTRAINT "batches_store_reserved_check" CHECK (reserved_quantity >= 0 AND (reserved_quantity = 0 OR quantity_available >= reserved_quantity));
ALTER TABLE "product_batches" ADD CONSTRAINT "product_batches_company_id_product_id_id_key" UNIQUE(company_id,product_id,id);
CREATE TABLE "store_payment_methods" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE RESTRICT, code TEXT NOT NULL, label TEXT NOT NULL, instructions TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, UNIQUE(company_id,code), UNIQUE(company_id,id));
CREATE TABLE "store_shipping_methods" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE RESTRICT, kind TEXT NOT NULL, label TEXT NOT NULL, fee DECIMAL(12,2) NOT NULL CHECK(fee >= 0), districts TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], pickup_address TEXT, enabled BOOLEAN NOT NULL DEFAULT true, UNIQUE(company_id,id));
CREATE TABLE "store_carts" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, account_id TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,account_id), UNIQUE(company_id,id), FOREIGN KEY(company_id,account_id) REFERENCES customer_accounts(company_id,id) ON DELETE CASCADE);
CREATE TABLE "store_cart_items" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, cart_id TEXT NOT NULL, product_id TEXT NOT NULL, presentation_id TEXT, quantity DECIMAL(14,3) NOT NULL CHECK(quantity > 0), UNIQUE(cart_id,product_id), FOREIGN KEY(company_id,cart_id) REFERENCES store_carts(company_id,id) ON DELETE CASCADE, FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id) ON DELETE RESTRICT);
CREATE TABLE "store_quotes" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, account_id TEXT NOT NULL, cart_version INTEGER NOT NULL, settings_version INTEGER NOT NULL, snapshot JSONB NOT NULL, expires_at TIMESTAMP(3) NOT NULL, UNIQUE(company_id,id), FOREIGN KEY(company_id,account_id) REFERENCES customer_accounts(company_id,id) ON DELETE RESTRICT);
CREATE INDEX "store_quotes_expires_at_idx" ON store_quotes(expires_at);
CREATE TYPE "StockReservationState" AS ENUM ('ACTIVE','CONSUMED','RELEASED','EXPIRED');
CREATE TABLE "stock_reservations" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, product_id TEXT NOT NULL, owner_id TEXT NOT NULL, quantity DECIMAL(14,3) NOT NULL CHECK(quantity > 0), expires_at TIMESTAMP(3) NOT NULL, state "StockReservationState" NOT NULL DEFAULT 'ACTIVE', UNIQUE(owner_id,product_id), UNIQUE(company_id,product_id,id), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id) ON DELETE RESTRICT);
CREATE INDEX "stock_reservations_state_expires_at_idx" ON stock_reservations(state,expires_at);
CREATE TABLE "stock_reservation_allocations" (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, product_id TEXT NOT NULL, reservation_id TEXT NOT NULL, batch_id TEXT NOT NULL, quantity DECIMAL(14,3) NOT NULL CHECK(quantity > 0), UNIQUE(reservation_id,batch_id), FOREIGN KEY(company_id,product_id,reservation_id) REFERENCES stock_reservations(company_id,product_id,id) ON DELETE RESTRICT, FOREIGN KEY(company_id,product_id,batch_id) REFERENCES product_batches(company_id,product_id,id) ON DELETE RESTRICT);
